import{_ as e,c as t,o as r,ah as n}from"./chunks/framework.Ch_PcVtW.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART2/14.md","filePath":"ja-jp/Management2/PART2/14.md"}'),o={name:"ja-jp/Management2/PART2/14.md"};function p(s,a,i,l,_,d){return r(),t("div",null,[...a[0]||(a[0]=[n('<p>► 2023/06</p><h2 id="ツアー初日前夜「久しぶりに眠れなかった」理由" tabindex="-1">ツアー初日前夜「久しぶりに眠れなかった」理由 <a class="header-anchor" href="#ツアー初日前夜「久しぶりに眠れなかった」理由" aria-label="Permalink to &quot;ツアー初日前夜「久しぶりに眠れなかった」理由&quot;">​</a></h2><p>#責任感 #プレッシャー #体制の向上 #感謝 #SKYHI</p><h3 id="「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」" tabindex="-1">「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」 <a class="header-anchor" href="#「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」" aria-label="Permalink to &quot;「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」&quot;">​</a></h3><p><strong>2023年6月18日、SKY-HIは東京・大阪の4公演で約4万人を動員した、自身史上最大のツアー『SKY-HI ARENA TOUR 2023 -BOSSDOM-』を終えた。今回は、「久々にライブ初日前に眠れなかった」というSKY-HIの話を紹介する。インタビューは東京公演と大阪公演の間に行った。</strong></p><p>「BOSSDOM」では、久しぶりに初日前に眠れなかったんですよね。りょんりょん(ボイストレーナーの佐藤涼子氏)にその話をしたら、「初日の前で熟睡できるアーティストなんていないわよ」って言われたけど。(笑)</p><p>たぶん緊張していたんでしょうね。初日が映像の収録ということもなかなかないし、それにもかかわらず当日やってみないと分かんない」っていうこともいっぱいあったし、立場や責任、タイミングも含めて「外しちゃいけない」感はすごくありました。</p><p>一方で最近、フェスにしろ何にしろ、本番が1番良くて。たとえいろんな不安なことがあっても、本番が1番良いことが続いていて、「いいね、俺！」なんて思ってたんです。それができている要因は1つじゃない感じはします。所属アーティストのおかげ、スクッフのおかげ、ファンのおかげ、いろいろなことのおかげの気がしますね。あと、両親のおかげ(笑)。</p><p>今、武道館公演(SKY-HI Tour 2017 Final “WELIVE” in BUDOKAN)をしたときと同じ現場マネジャーがBMSGに転職して、再び自分に付いているんですよ。それで当時のことを思い出すんですが、武道館公演をするとなっても全く自分に対するバックアップ体制がなかったんです。マネジャー以外のスタッフもいないし、マッサージの方もいないし、ボイストレーナーもいないし、筋トレのトレーナーもいない状態。当時、大きくなったアーティストの友達のバックステージに行くと、ケータリングはあるし、マッサージの方もいるし、トレーナーもいるし、ほかにもいろいろそろっているんですよ。びっくりしちゃいました。自分にもそれが欲しかったというわけではないですが、今振り返るとやっぱり明らかにパフォーマンスやクリエーティブに集中できていないこともありました。おかげで「パフォーマンスを上げるために何をすればいいか」を1つひとつ考えてアーテイスト兼プロデューサーとしての体制を整えられた6年間でしたし、現在本当にサポートしてもらっていることに強く感謝できるので、結果としては必要な時期でした。</p><h3 id="プレッシャーはよい影響を与えてくれる" tabindex="-1">プレッシャーはよい影響を与えてくれる <a class="header-anchor" href="#プレッシャーはよい影響を与えてくれる" aria-label="Permalink to &quot;プレッシャーはよい影響を与えてくれる&quot;">​</a></h3><p><strong>自身のチームが整って、ステージでのパフォーマンスが向上する一方で、「ステージの表でも裏でも、自分の責任を感じているところがある」とも語る。</strong></p><p>たぶん、どちらが正しいとかではなく、責任を背負ったほうがいパフォーマンスができるタイプの人とそうでない人がいると思うんです。自分の場合は確実に前者でいろいろなケアをしていただいたり、みんなからの期待をしていただいたりしてしまうと、背負うものの重さを強く感じてどんどんとプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれています。元からの気質なのか、そういう環境になってから身についたものなのか分かりませんが。ただ、そうしたプレッシャーのおかげで、初日前はめちゃくちゃ緊張しましたね。</p><p>プレッシャーはプレッシャーであって、そこに良いプレッシャーも悪いプレッシャーもないんですが、それをいい形に昇華できている状態はいいなと感じています。ライブが終わってからスタッフやアーティスト、トレーニー、友達のみんなが遠慮せず楽屋に来るのもうれしかったですし、すごく楽しかったですね。</p>',13)])])}const m=e(o,[["render",p]]);export{h as __pageData,m as default};
